// Browser loader of the Wasm modules (AD-rust-4): `await init()` once per module, the instance cached.
// The glue is generated by `npm run build:wasm` into rust/pkg/<module>/; its own
// `new URL('<module>_bg.wasm', import.meta.url)` makes Vite emit the .wasm as a hashed asset (AD-rust-2).
// A module is added to this table when a tool needs it; the example is the template.
type Exemple = typeof import('../../../rust/pkg/exemple/exemple.js');
type Coeur = typeof import('../../../rust/pkg/coeur/coeur.js');

interface Modules {
  exemple: Exemple;
  coeur: Coeur;
}

const importeurs: { [N in keyof Modules]: () => Promise<Modules[N] & { default: () => Promise<unknown> }> } = {
  exemple: () => import('../../../rust/pkg/exemple/exemple.js'),
  coeur: () => import('../../../rust/pkg/coeur/coeur.js'),
};

const cache = new Map<keyof Modules, Promise<Modules[keyof Modules]>>();

/** Loads a module on first use; later calls give back the same instance. */
export function chargerModule<N extends keyof Modules>(nom: N): Promise<Modules[N]> {
  let chargement = cache.get(nom);
  if (!chargement) {
    chargement = importeurs[nom]().then(async (m) => {
      await m.default();
      return m;
    });
    // A failed load is not kept: the next call tries again.
    chargement.catch(() => cache.delete(nom));
    cache.set(nom, chargement);
  }
  return chargement as Promise<Modules[N]>;
}
